const [open, setOpen] = React.useState(false);
const [search, setSearch] = React.useState('');
const listboxId = React.useId();

const selectedOption = options.find((opt) => opt.value === value);
const handleOpenChange = React.useCallback(
  (nextOpen: boolean) => {
    setOpen(nextOpen);
    onOpenChange?.(nextOpen);
  },
  [onOpenChange]
);

return (
  <Popover open={open} onOpenChange={handleOpenChange}>
    <PopoverTrigger asChild>
      <button
        id={id}
        type="button"
        role="combobox"
        aria-expanded={open}
        aria-controls={listboxId}
        disabled={disabled}
        className={cn(
          'flex h-8 w-full items-center justify-between rounded-md border border-[var(--color-border)] bg-[var(--color-form-control-bg)] px-3 py-1 text-xs shadow-sm transition-colors placeholder:text-[var(--color-text-muted)] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-border-emphasis)] disabled:cursor-not-allowed disabled:opacity-50',
          className
        )}
      >
        <span className="min-w-0 truncate text-left">
          {selectedOption
            ? (renderTriggerLabel?.(selectedOption) ?? selectedOption.label)
            : placeholder}
        </span>
        <ChevronsUpDown className="ml-2 size-3.5 shrink-0 opacity-50" />
      </button>
    </PopoverTrigger>
    {open ? (
      <PopoverContent
        id={listboxId}
        className="w-[var(--radix-popover-trigger-width)] p-0"
        align="start"
        sideOffset={4}
        collisionPadding={8}
        avoidCollisions
      >
        <CommandPrimitive
          className="flex size-full flex-col overflow-hidden rounded-md bg-[var(--color-surface)]"
          shouldFilter={false}

{options
  .filter((opt) => {
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return (
      opt.label.toLowerCase().includes(q) ||
      opt.value.toLowerCase().includes(q) ||
      (opt.description?.toLowerCase().includes(q) ?? false)
    );
  })
  .map((option) => {
    const isSelected = option.value === value;
    return (
      <CommandPrimitive.Item
        key={option.value}
        value={option.value}
        disabled={option.disabled}
        aria-disabled={option.disabled === true}
        onSelect={() => {
          if (option.disabled) {
            return;
          }
          onValueChange(option.value);
          setOpen(false);
          setSearch('');
        }}
        className={cn(
          'relative flex w-full cursor-default select-none items-center rounded-sm px-2 py-1.5 text-xs outline-none data-[selected=true]:bg-[var(--color-surface-raised)] data-[selected=true]:text-[var(--color-text)]',
          option.disabled && 'cursor-not-allowed opacity-60'
        )}
      >
        {renderOption ? (
          renderOption(option, isSelected, search)
        ) : (
          <>
            {isSelected ? <Check className="mr-2 size-3.5 shrink-0" /> : null}
            <div className="min-w-0 flex-1">
              <p className="truncate font-medium text-[var(--color-text)]">
                {option.label}
              </p>
              {option.description ? (
                <p className="truncate text-[var(--color-text-muted)]">
                  {option.description}
                </p>
              ) : null}
            </div>
          </>
        )}
      </CommandPrimitive.Item>
    );

const isSchedule = props.mode === 'schedule';
const schedule = isSchedule ? (props.schedule ?? null) : null;
const isEditing = isSchedule && !!schedule;
// Team name: always present for launch mode, may be absent in schedule mode (standalone page)
const propsTeamName = props.teamName ?? '';
const [selectedTeamName, setSelectedTeamName] = useState('');
const { teamByName, openDashboard } = useStore(
  useShallow((s) => ({
    teamByName: s.teamByName,
    openDashboard: s.openDashboard,
  }))
);
const openTeamTab = useStore((s) => s.openTeamTab);
const teamOptions = useMemo(
  () =>
    Object.values(teamByName)
      .sort((a, b) => a.teamName.localeCompare(b.teamName))
      .map((team) => ({
        value: team.teamName,
        label: team.displayName || team.teamName,
        description: team.description || undefined,
        meta: { color: team.color },
      })),
  [teamByName]
);
const effectiveTeamName = propsTeamName || selectedTeamName;
const defaultProjectPath = isLaunchMode ? props.defaultProjectPath : undefined;
const hydrationSourceRevision = useRef<string | undefined>(undefined);
const [launchHydratedTeamName, setLaunchHydratedTeamName] = useState<string | null>(null);
const savedLaunchSource = useLaunchDialogSavedRequest(open, isLaunchMode, effectiveTeamName);
const ownerHydrationPending =
  savedLaunchSource.host &&
  (!savedLaunchSource.ready || launchHydratedTeamName !== savedLaunchSource.key);
const needsTeamSelector = isSchedule && !propsTeamName;

{needsTeamSelector ? (
  <div className="space-y-1.5">
    <Label className="text-xs">{t('launch.schedule.team')}</Label>
    <Combobox
      options={teamOptions}
      value={selectedTeamName}
      onValueChange={(name) => { setSelectedTeamName(name); setScheduleFormTouched(true); setLocalError(null); }}
      placeholder={t('launch.schedule.selectTeam')}
      searchPlaceholder={t('launch.schedule.searchTeams')}
      emptyMessage={
        teamOptions.length === 0
          ? t('launch.schedule.noTeams')
          : t('launch.schedule.noMatches')
      }
      disabled={teamOptions.length === 0}
      renderOption={(option, isSelected) => {
        const colorName = option.meta?.color as string | undefined;
        const colorSet = colorName
          ? getTeamColorSet(colorName)
          : nameColorSet(option.label);
        return (
          <>
            {isSelected ? (
              <Check className="mr-2 size-3.5 shrink-0 text-[var(--color-text)]" />
            ) : (
              <span
                className="mr-2 size-3.5 shrink-0 rounded-full"
                style={{ backgroundColor: colorSet.text }}
              />
            )}
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-1.5">
                {isSelected ? (
                  <span
                    className="size-2 shrink-0 rounded-full"
                    style={{ backgroundColor: colorSet.text }}
                  />
                ) : null}
                <p className="truncate font-medium text-[var(--color-text)]">
                  {option.label}
                </p>
              </div>
              {option.description ? (
                <p className="truncate text-[var(--color-text-muted)]">
                  {option.description}
                </p>
              ) : null}
            </div>
          </>
        );
      }}
    />

) : null}

{isTaskFirstSchedule && savedPromptReview?.teamName === effectiveTeamName ? (
  <HistoricalPromptReview prompt={savedPromptReview.prompt} confirmed={savedPromptReview.confirmed}
    onConfirmedChange={(confirmed) => setSavedPromptReview((current) => current && ({ ...current, confirmed }))} />
) : null}

const { open, enabled, teamName, scheduleId, reviewed } = input;
const [review, setReview] = useState<SavedPromptReview | null>(null);

useEffect(() => setReview(null), [teamName, scheduleId, open]);
useEffect(() => {
  if (!open || !enabled || !teamName) return;
  let cancelled = false;
  void api.teams.getSavedRequest(teamName).then((saved) => {
    if (cancelled) return;
    const prompt = saved?.prompt?.trim() ?? '';
    if (!prompt) {
      setReview(null);
      return;
    }
    setReview((current) =>
      current?.teamName === teamName && current.prompt === prompt
        ? current
        : { teamName, prompt, confirmed: reviewed }
    );
  }).catch(() => {
    // The submit path performs the authoritative read and reports errors.
  });
  return () => { cancelled = true; };
}, [enabled, open, reviewed, teamName]);

return [review, setReview] as const;
